window.__finlexDocLoaded(10200,{"id":10200,"articles":[{"id":1000831,"no":"Overview","heading":"Scope & Core Objective (Public Summary)","text":"Requires all equity investments without significant influence or control to be measured at Fair Value Through Net Income (FVTPL), with an optional measurement alternative for equity securities without a readily determinable fair value.","seq":0},{"id":1000832,"no":"ASC 321-10","heading":"Mandatory FVTPL & Measurement Alternative for Private Equity","text":"• Default Rule (ASC 321-10-35-1): All equity securities (outside equity method/consolidation) are measured at fair value with changes recognized in NET INCOME — NO FVOCI election exists under US GAAP.\n• Measurement Alternative (ASC 321-10-35-2): For equity securities without a readily determinable fair value, entities may elect cost minus impairment, plus or minus observable price changes in orderly transactions for identical/similar investments of the same issuer.","seq":1},{"id":1000833,"no":"US GAAP vs. IFRS / CAS","heading":"Key Cross-Framework Differences","text":"• Major Divergence from IFRS 9 / CAS 22: IFRS 9.5.7.5 allows an irrevocable FVOCI election for strategic non-trading equity investments (never recycled to P&L); US GAAP (ASC 321) PROHIBITS FVOCI for equity securities — all fair value swings hit Net Income.","seq":2},{"id":1000834,"no":"Official Access","heading":"Official FASB Codification & Reference Entry","text":"Official Portal (FASB Accounting Standards Codification®): https://asc.fasb.org/\nStatus: in_force (FASB ASC free Basic View available at https://asc.fasb.org/).","seq":3}]});
